import { motion } from "framer-motion";
import { useState } from "react";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    message: "",
  });

  const [status, setStatus] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus("Sending...");

    try {
      const res = await fetch("http://localhost:5000/contact", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (res.ok) {
        setStatus("Message sent successfully ✅");
        setForm({ name: "", email: "", message: "" });
      } else {
        setStatus("Something went wrong ❌");
      }
    } catch (err) {
      setStatus("Server error ❌");
    }
  };

  return (
    <section id="contact" className="scroll-mt-24 bg-black py-32 px-6">
      <div className="max-w-7xl mx-auto grid md:grid-cols-2 gap-16 items-center">

        {/* LEFT */}
        <motion.div
          initial={{ opacity: 0, x: -40 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <h2 className="text-4xl md:text-5xl font-bold">
            Get in <span className="text-red-600">Touch</span>
          </h2>

          <p className="mt-6 text-gray-400 max-w-lg">
            For enquiries related to memberships, programs, or branch details,
            get in touch with us and our team will assist you.
          </p>

          <p className="mt-4 text-sm text-gray-500">
            Our team typically responds within 24 hours.
          </p>
        </motion.div>

        {/* FORM */}
        <motion.form
          onSubmit={handleSubmit}
          initial={{ opacity: 0, x: 40 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="bg-zinc-900/70 border border-white/10 rounded-2xl p-10 space-y-6"
        >
          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={form.name}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-red-600 outline-none"
          />

          <input
            type="email"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-red-600 outline-none"
          />

          <textarea
            name="message"
            rows="4"
            placeholder="Message"
            value={form.message}
            onChange={handleChange}
            required
            className="w-full bg-black border border-white/10 rounded-lg px-4 py-3 focus:border-red-600 outline-none resize-none"
          />

          <button
            type="submit"
            className="w-full bg-red-600 hover:bg-red-700 py-3 rounded-lg font-semibold transition"
          >
            Send Message
          </button>

          {status && (
            <p className="text-sm text-center text-gray-400">{status}</p>
          )}
        </motion.form>
      </div>

      <p className="mt-24 text-center text-sm text-gray-500">
        © 2025 Bodyzeal Fitworks. All rights reserved.
      </p>
    </section>
  );
}
